// Parity tests: the browser-side engine must reproduce the REAL FastAPI outputs (golden.json, generated by
// backend/tools/make_golden.py from the committed snapshot) using only the exported static files.
import { readFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { beforeAll, describe, expect, it } from "vitest";
import golden from "./golden.json";
import { fetchMap, fetchPoint, fetchWorldPoint, fetchProbMap, fetchProbMeta, fetchProbPoint, fetchRun, fetchRuns, fetchStatus, setDataBase } from "./staticData";
import { ApiError } from "./types";

const dataDir = resolve(dirname(fileURLToPath(import.meta.url)), "../static-data");

let hideW50 = false;   // the detailed 0.5 deg files are not in git; tests of the 2 deg layer must not depend on them
beforeAll(() => {
  // Serve the exported files from disk in place of the network.
  globalThis.fetch = (async (input: RequestInfo | URL) => {
    const path = String(input).replace(/^data\//, "");
    try {
      if (hideW50 && (path.includes("/w50/") || path.includes("/wt/"))) throw new Error("hidden");
      const buf = readFileSync(resolve(dataDir, path));
      return {
        ok: true, status: 200,
        json: async () => JSON.parse(buf.toString("utf8")),
        arrayBuffer: async () => buf.buffer.slice(buf.byteOffset, buf.byteOffset + buf.byteLength),
      } as unknown as Response;
    } catch {
      return { ok: false, status: 404, json: async () => ({}), arrayBuffer: async () => new ArrayBuffer(0) } as unknown as Response;
    }
  }) as typeof fetch;
  setDataBase("data/");
});

const G = golden as unknown as Record<string, any>; // eslint-disable-line @typescript-eslint/no-explicit-any
const near = (a: number, b: number, tol = 1e-5) => Math.abs(a - b) <= tol;

describe("run list and metadata", () => {
  it("lists runs newest first and the status mirrors the index", async () => {
    const runs = (await fetchRuns()).runs;
    expect(runs[0].run_id).toBe(G.latest_run);
    const st = await fetchStatus();
    expect(st.latest_run).toBe(G.latest_run);
    expect(st.mode).toBe("static");
    expect(st.probability?.latest_run).toBe(G.prob_run);
  });
  it("run metadata matches the API (steps, valid times, delay, domain, grid)", async () => {
    const m = await fetchRun();
    const g = G.meta;
    expect(m.run_id).toBe(g.run_id);
    expect(m.steps_h).toEqual(g.steps_h);
    expect(m.valid_times_utc).toEqual(g.valid_times_utc);
    expect(m.interval_durations_h).toEqual(g.interval_durations_h);
    expect(m.domain).toEqual(g.domain);
    expect(m.grid).toEqual(g.grid);
    expect(m.availability_delay_h).toBe(g.availability_delay_h);
    expect(m.attribution).toContain("ECMWF");
  });
  it("probability metadata matches the API", async () => {
    const p = await fetchProbMeta();
    expect(p.run_id).toBe(G.prob_meta.run_id);
    expect(p.thresholds_mm).toEqual(G.prob_meta.thresholds_mm);
    expect(p.windows).toEqual(G.prob_meta.windows);
  });
});

describe("map grids equal the API", () => {
  const cells = (a: number[][]) => a.flat();
  it("24 h window total (full grid): >= 99.9 % of cells identical, all within 0.1 mm", async () => {
    const e = G.maps.map_window24;
    const m = await fetchMap(G.latest_run, e.step_h, "precip", "window", 24);
    expect(m.kind).toBe("window");
    expect(m.accumulation_hours).toBe(24);
    expect(m.valid_time_utc).toBe(e.valid_time_utc);
    const a = cells(m.values), b = cells(e.values as number[][]);
    expect(a.length).toBe(b.length);
    const diffs = a.map((v, i) => Math.abs(v - b[i]));
    expect(Math.max(...diffs)).toBeLessThanOrEqual(0.1 + 1e-6);          // float32 rounding ties only
    expect(diffs.filter((d) => d > 1e-5).length / a.length).toBeLessThan(0.001);
  });
  it("temperature (full grid) is identical to 0.1 degC", async () => {
    const e = G.maps.map_temp;
    const m = await fetchMap(G.latest_run, e.step_h, "temp", "interval");
    expect(m.units).toBe("°C");
    expect(m.kind).toBe("instant");
    const a = cells(m.values), b = cells(e.values as number[][]);
    expect(Math.max(...a.map((v, i) => Math.abs(v - b[i])))).toBeLessThanOrEqual(0.1 + 1e-6);
    expect(a.filter((v, i) => Math.abs(v - b[i]) > 1e-5).length / a.length).toBeLessThan(0.002);
  });
  it.each(["map_interval", "map_cumulative", "map_cloud", "map_wind"])("%s matches the API at sampled cells", async (name) => {
    const e = G.maps[name];
    const variable = e.variable as "precip" | "cloud" | "wind";
    const kind = e.kind === "instant" ? "interval" : e.kind;
    const m = await fetchMap(e.run_id, e.step_h, variable, kind);
    expect([m.values.length, m.values[0].length]).toEqual(e.shape);
    expect(m.units).toBe(e.units);
    expect(m.accumulation_hours).toBe(e.accumulation_hours);
    for (const [y, x, v] of e.samples as [number, number, number][]) expect(near(m.values[y][x], v, variable === "wind" ? 0.1 + 1e-6 : 1e-5)).toBe(true);
    if (variable === "wind") {
      for (const [y, x, v] of e.u_samples as [number, number, number][]) expect(near(m.u![y][x], v, 0.1 + 1e-6)).toBe(true);
      for (const [y, x, v] of e.v_samples as [number, number, number][]) expect(near(m.v![y][x], v, 0.1 + 1e-6)).toBe(true);
    }
  });
});

describe("place series equal the API", () => {
  it.each(Object.keys(golden.points))("%s", async (name) => {
    const e = G.points[name];
    const p = await fetchPoint(G.latest_run, e.lat, e.lon);
    expect(p.grid_point).toEqual(e.grid_point);
    expect(p.method).toBe(e.method);
    expect(p.series.length).toBe(e.series.length);
    p.series.forEach((s, i) => {
      const x = e.series[i];
      expect(s.step_h).toBe(x.step_h);
      expect(s.valid_time_utc).toBe(x.valid_time_utc);
      expect(s.interval_hours).toBe(x.interval_hours);
      expect(near(s.cumulative_mm, x.cumulative_mm, 0.0101)).toBe(true);
      if (x.interval_mm === null) expect(s.interval_mm).toBeNull(); else expect(near(s.interval_mm!, x.interval_mm, 0.0101)).toBe(true);
      expect(near(s.temp_c!, x.temp_c, 0.1 + 1e-6)).toBe(true);
      expect(s.cloud_pct).toBe(x.cloud_pct);
      expect(near(s.wind_speed_ms!, x.wind_speed_ms, 0.1 + 1e-6)).toBe(true);
      // wind direction is only meaningful above a few tenths of a m/s; compare circularly with a small tolerance
      if (x.wind_speed_ms >= 1) {
        const d = Math.abs(s.wind_from_deg! - x.wind_from_deg);
        expect(Math.min(d, 360 - d)).toBeLessThanOrEqual(3);
      }
    });
  });
});

describe("probabilities equal the API", () => {
  it("map (full grid)", async () => {
    const e = G.prob_map;
    const m = await fetchProbMap(G.prob_run, e.window.end_h, 10);
    expect(m.window).toEqual(e.window);
    expect(m.valid_time_utc).toBe(e.valid_time_utc);
    expect(m.values).toEqual(e.values);                                   // integers: exact
  });
  it("place table", async () => {
    const e = G.prob_point;
    const p = await fetchProbPoint(G.prob_run, e.lat, e.lon);
    expect(p.grid_point).toEqual(e.grid_point);
    expect(p.thresholds_mm).toEqual(e.thresholds_mm);
    expect(p.windows).toEqual(e.windows);
  });
});

describe("validation errors match the API (status and message)", () => {
  const run = async (name: string) => {
    const e = G.errors[name];
    const url = new URL("http://x" + e.path);
    const q = (k: string) => url.searchParams.get(k);
    const seg = url.pathname.split("/");
    const id = seg[seg.indexOf(seg.includes("probability") ? "probability" : "runs") + 1];
    try {
      if (url.pathname.includes("/probability/")) {
        if (url.pathname.endsWith("/map")) await fetchProbMap(id, Number(q("window_end")), Number(q("threshold")));
        else await fetchProbPoint(id, Number(q("lat")), Number(q("lon")));
      } else if (url.pathname.endsWith("/point")) await fetchPoint(id, Number(q("lat")), Number(q("lon")));
      else await fetchMap(id, Number(q("step")), q("variable") as "precip", q("kind") as "window", Number(q("hours") ?? 24));
    } catch (err) {
      return err as ApiError;
    }
    throw new Error(`${name}: expected an error`);
  };
  it.each(Object.keys(golden.errors))("%s", async (name) => {
    const err = await run(name);
    expect(err).toBeInstanceOf(ApiError);
    expect(err.status).toBe(G.errors[name].status);
    expect(err.message).toBe(G.errors[name].detail);
  });
});

describe("light place fetch (used for the previous-run comparison)", () => {
  it("returns the rain series without downloading temperature/cloud/wind", async () => {
    const seen: string[] = [];
    const real = globalThis.fetch;
    globalThis.fetch = ((u: RequestInfo | URL, init?: RequestInit) => { seen.push(String(u)); return real(u, init); }) as typeof fetch;
    setDataBase("data/");                                   // clears the memo cache so every file is requested again
    try {
      const p = await fetchPoint(G.older_run, 22.57, 88.36, { light: true });
      expect(p.series[1].temp_c).toBeUndefined();
      expect(p.series[1].cumulative_mm).toBeGreaterThanOrEqual(0);
      expect(seen.some((s) => s.endsWith("cum.bin"))).toBe(true);
      expect(seen.some((s) => /temp\.bin|cloud\.bin|u\.bin|v\.bin/.test(s))).toBe(false);
    } finally { globalThis.fetch = real; }
  });
});

import worldGolden from "./world-golden.json";
describe("world overview (2 degree block means)", () => {
  beforeAll(() => { hideW50 = true; setDataBase("data/"); });
  const WG = worldGolden as unknown as { run_id: string; cells: [number, number][]; cases: { params: Record<string, string | number>; lats: number[]; lons: number[]; units: string; values: number[]; u: number[] | null }[] };
  for (const c of WG.cases) {
    it(`matches the real API: ${JSON.stringify(c.params)}`, async () => {
      const p = c.params;
      const m = await fetchMap(WG.run_id, p.step as number, p.variable as "precip", (p.kind as "interval") ?? "interval", (p.hours as number) ?? 24, "world");
      expect([m.lats[0], m.lats[m.lats.length - 1], m.lats.length]).toEqual(c.lats);
      expect([m.lons[0], m.lons[m.lons.length - 1], m.lons.length]).toEqual(c.lons);
      expect(m.units).toBe(c.units);
      WG.cells.forEach(([r, k], i) => {
        expect(near(m.values[r][k], c.values[i], 1e-6)).toBe(true);
        if (c.u) expect(near(m.u![r][k], c.u[i], 0.101)).toBe(true);   // files store 0.01 m/s, so a 0.1 rounding boundary can flip (same rule as the India parity tests)
      });
    });
  }
  it("india scope is unchanged by the new parameter", async () => {
    const a = await fetchMap(WG.run_id, 24, "temp", "interval", 24);
    expect(a.lats.length).toBeGreaterThan(100);
  });
});


import { existsSync } from "node:fs";
describe("detailed 0.5 degree world (per-step files; present only after a local export with --world50)", () => {
  const have = existsSync(resolve(dataDir, "runs", worldGolden.run_id, "w50", "cum_8.bin"));
  beforeAll(() => { hideW50 = false; setDataBase("data/"); });
  it.skipIf(!have)("is 4x finer than the 2 degree layer and consistent with it (block means of the same data)", async () => {
    const fine = await fetchMap(worldGolden.run_id, 24, "temp", "interval", 24, "world");
    expect(fine.lats.length).toBe(360); expect(fine.lons.length).toBe(720);
    expect(Math.abs(fine.lons[1] - fine.lons[0])).toBeCloseTo(0.5, 6);
    hideW50 = true; setDataBase("data/");
    const coarse = await fetchMap(worldGolden.run_id, 24, "temp", "interval", 24, "world");
    hideW50 = false; setDataBase("data/");
    expect(coarse.lats.length).toBe(90);
    // the mean of each 4 x 4 block of 0.5 deg cells must equal the 2 deg cell (same data, same averaging)
    let worst = 0;
    for (const [r, c] of [[10, 20], [45, 100], [60, 150], [80, 30]]) {
      let s = 0;
      for (let y = 0; y < 4; y++) for (let x = 0; x < 4; x++) s += fine.values[r * 4 + y][c * 4 + x];
      worst = Math.max(worst, Math.abs(s / 16 - coarse.values[r][c]));
    }
    expect(worst).toBeLessThan(0.15);   // both are rounded to 0.1 degC
  });
  it.skipIf(!have)("rain: window = difference of cumulative files, never negative; wind has components", async () => {
    const w = await fetchMap(worldGolden.run_id, 48, "precip", "window", 24, "world");
    expect(w.units).toBe("mm");
    expect(Math.min(...w.values.map((r) => Math.min(...r)))).toBeGreaterThanOrEqual(0);
    const wind = await fetchMap(worldGolden.run_id, 24, "wind", "interval", 24, "world");
    expect(wind.u && wind.v).toBeTruthy();
    expect(wind.values[100][100]).toBeCloseTo(Math.hypot(wind.u![100][100], wind.v![100][100]), 0);
  });
});


describe("world-wide place forecast (1 degree tiles)", () => {
  const rid = worldGolden.run_id;
  const have = existsSync(resolve(dataDir, "runs", rid, "wt", "cum_0_0.bin"));
  beforeAll(() => { hideW50 = false; setDataBase("data/"); });
  it.skipIf(!have)("returns a full series with sane values anywhere on Earth", async () => {
    for (const [la, lo] of [[48.86, 2.35], [-33.87, 151.21], [40.71, -74.0], [-1.29, 36.82], [64.15, -21.94], [-77.0, 160.0]]) {
      const p = await fetchWorldPoint(rid, la, lo);
      expect(p.world).toBe(true);
      expect(p.series.length).toBeGreaterThan(20);
      expect(Math.abs(p.grid_point.lat - la)).toBeLessThanOrEqual(0.51);
      expect(Math.abs(p.grid_point.lon - lo)).toBeLessThanOrEqual(0.51);
      let prev = -1;
      for (const s of p.series) {
        expect(s.cumulative_mm).toBeGreaterThanOrEqual(prev - 0.11); prev = s.cumulative_mm;   // 0.1 mm storage steps
        if (s.interval_mm !== null) expect(s.interval_mm).toBeGreaterThanOrEqual(0);
        expect(s.temp_c!).toBeGreaterThan(-90); expect(s.temp_c!).toBeLessThan(60);
        expect(s.cloud_pct!).toBeGreaterThanOrEqual(0); expect(s.cloud_pct!).toBeLessThanOrEqual(100);
        expect(s.wind_speed_ms!).toBeGreaterThanOrEqual(0);
      }
    }
  });
  it.skipIf(!have)("agrees with the 0.5 degree map files (same data averaged differently)", async () => {
    const [la, lo] = [48.86, 2.35];
    const p = await fetchWorldPoint(rid, la, lo);
    const i = p.series.findIndex((s) => s.step_h === 24);
    const m = await fetchMap(rid, 24, "temp", "interval", 24, "world");
    // the four 0.5 deg cells that make up this 1 deg cell
    const gy = (p.grid_point.lat - m.lats[0]) / -0.5, gx = (p.grid_point.lon - m.lons[0]) / 0.5;
    const ys = [Math.round(gy - 0.5), Math.round(gy + 0.5)], xs = [Math.round(gx - 0.5), Math.round(gx + 0.5)];
    const mean = (ys.flatMap((y) => xs.map((x) => m.values[y][x])).reduce((a, b) => a + b, 0)) / 4;
    expect(Math.abs(mean - p.series[i].temp_c!)).toBeLessThan(0.3);
  });
  it.skipIf(!have)("clear error when the tile files are not deployed", async () => {
    hideW50 = true; setDataBase("data/");
    await expect(fetchWorldPoint(rid, 10, 10)).rejects.toBeInstanceOf(ApiError);
    hideW50 = false; setDataBase("data/");
  });
});
